      "stopLoss": "1 point below the low of the confirmation candle (-25 pts on Index)",
      "target1": "Previous swing high (+50 pts / 1:2 Risk to Reward)",
      "target2": "Major day ceiling (+75 pts / 1:3 Risk to Reward)",
